insert into ingestion_task (
    id, kb_id, source_type, client_request_id, request_hash, dedupe_strategy,
    status, total_count, success_count, failure_count, running_count,
    created_by, updated_by, created_at, updated_at, finished_at
) values (
    #{id}, #{kbId}, #{sourceType}, #{clientRequestId}, #{requestHash}, #{dedupeStrategy},
    #{status}, #{totalCount}, #{successCount}, #{failureCount}, #{runningCount},
    #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}, #{finishedAt}
)

insert into ingestion_task_item (
    id, task_id, asset_id, target_index_generation, file_name, file_hash,
    stage, status, progress, dedupe_result, duplicate_asset_id,
    error_code, error_message, created_at, updated_at, finished_at
) values (
    #{id}, #{taskId}, #{assetId}, #{targetIndexGeneration}, #{fileName}, #{fileHash},
    #{stage}, #{status}, #{progress}, #{dedupeResult}, #{duplicateAssetId},
    #{errorCode}, #{errorMessage}, #{createdAt}, #{updatedAt}, #{finishedAt}
)

mapper.select:
select 
from ingestion_task
where id = #{taskId} and kb_id = #{kbId}

select 
from ingestion_task
where kb_id = #{kbId}
and status = #{status}
order by created_at desc, id desc
limit #{limit}

mapper.update:
update ingestion_task_item
set stage = #{nextStage}, progress = greatest(progress, #{progress}),
    error_code = null, error_message = null, updated_at = #{updatedAt}
where id = #{itemId} and task_id = #{taskId}
  and status = 'RUNNING' and stage = #{expectedStage}
  and exists (
      select 1 from ingestion_task it
      where it.id = ingestion_task_item.task_id and it.kb_id = #{kbId}
  )

mapper.select:
select id from ingestion_task_item
where id = #{itemId} and status = 'RUNNING' and stage = #{expectedStage}
for update

mapper.update:
update ingestion_task_item
set stage = 'ASKABLE', status = 'SUCCESS', progress = 100,
    error_code = null, error_message = null,
    updated_at = #{updatedAt}, finished_at = #{updatedAt}
where id = #{itemId} and task_id = #{taskId}
  and status = 'RUNNING' and stage = #{expectedStage}
  and exists (
      select 1 from ingestion_task it
      where it.id = ingestion_task_item.task_id and it.kb_id = #{kbId}
  )

update ingestion_task_item
set status = 'FAILED', progress = greatest(progress, #{progress}),
    error_code = #{errorCode}, error_message = #{errorMessage},
    updated_at = #{updatedAt}, finished_at = #{updatedAt}
where id = #{itemId} and task_id = #{taskId}
  and status = 'RUNNING' and stage = #{expectedStage}
  and exists (
      select 1 from ingestion_task it
      where it.id = ingestion_task_item.task_id and it.kb_id = #{kbId}
  )

mapper.select:
select coalesce(max(target_index_generation), 0)
from ingestion_task_item
where asset_id = #{assetId}

select target_index_generation
from ingestion_task_item
where id = #{itemId} and asset_id = #{assetId}

mapper.update:
update ingestion_task_item
set target_index_generation = #{targetIndexGeneration}, updated_at = #{updatedAt}
where id = #{itemId} and asset_id = #{assetId}
  and target_index_generation is null and status = 'RUNNING'
